-- Gold Warehouse Validation
SET NOCOUNT ON;

-- Check required tables are not empty
IF NOT EXISTS (SELECT 1 FROM dbo.FactTaxiDaily)
    THROW 50001, 'FactTaxiDaily is empty', 1;

IF NOT EXISTS (SELECT 1 FROM dbo.FactAirQualityDaily)
    THROW 50002, 'FactAirQualityDaily is empty', 1;

IF NOT EXISTS (SELECT 1 FROM dbo.DimDate)
    THROW 50003, 'DimDate is empty', 1;

IF NOT EXISTS (SELECT 1 FROM dbo.DimZone)
    THROW 50004, 'DimZone is empty', 1;

IF NOT EXISTS (SELECT 1 FROM dbo.DimFX)
    THROW 50005, 'DimFX is empty', 1;

IF NOT EXISTS (SELECT 1 FROM dbo.DimGDP)
    THROW 50006, 'DimGDP is empty', 1;

-- Check duplicate Taxi keys
IF EXISTS (
    SELECT 1
    FROM dbo.FactTaxiDaily
    GROUP BY trip_date, pickup_location_id
    HAVING COUNT(*) > 1
)
    THROW 50007, 'Duplicate keys in FactTaxiDaily', 1;

-- Check duplicate FX keys
IF EXISTS (
    SELECT 1
    FROM dbo.DimFX
    GROUP BY fx_date, currency
    HAVING COUNT(*) > 1
)
    THROW 50008, 'Duplicate keys in DimFX', 1;

-- Check Taxi dates exist in DimDate
IF EXISTS (
    SELECT 1
    FROM dbo.FactTaxiDaily AS f
    WHERE NOT EXISTS (
        SELECT 1
        FROM dbo.DimDate AS d
        WHERE d.full_date = f.trip_date
    )
)
    THROW 50009, 'Taxi dates missing from DimDate', 1;
